#pragma once#include <jsi/jsi.h>#include <vector>#include "uWebSockets/HttpParser.h"#include "uWebSockets/HttpContextData.h"namespace react_native_echo {class JSI_EXPORT RequestHostObject : public facebook::jsi::HostObject {private:  uWS::HttpRequest *httpRequest;  std::array<std::string, 6> keys = {"id",      // represent as the requestID                                   "headers", // obviously headers object                                   "method",  // GET, POST, or else                                   "url",                                   "formData",                                   "text",  };  facebook::jsi::Object headers(facebook::jsi::Runtime &rt);  facebook::jsi::String method(facebook::jsi::Runtime &rt);  facebook::jsi::Object url(facebook::jsi::Runtime &rt);  facebook::jsi::Object formData(facebook::jsi::Runtime &rt);  facebook::jsi::String text(facebook::jsi::Runtime &rt);public:  RequestHostObject(uWS::HttpRequest *req) : httpRequest(req) {};  facebook::jsi::Value get(facebook::jsi::Runtime &rt,                           const facebook::jsi::PropNameID &propNameID) override;  void set(facebook::jsi::Runtime &rt,           const facebook::jsi::PropNameID &propNameID,           const facebook::jsi::Value &value) override;  std::vector<facebook::jsi::PropNameID> getPropertyNames(facebook::jsi::Runtime &rt) override;};}